```html
<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>姐夫，就今天好不好？· 开局</title>
<style>
*{margin:0;padding:0;box-sizing:border-box;}
:root{
--color-bg:#0f0c0e;
--color-surface:rgba(28,22,26,0.78);
--color-surface-solid:#1c161a;
--color-border:rgba(200,160,130,0.18);
--color-text:#f0e6e0;
--color-text-muted:#a8968e;
--color-primary:#c77d6b;
--color-primary-hover:#db9180;
--color-accent:#e7b49b;
--color-gold:#cfaa7a;
--color-danger:#b8564a;
--space-xs:4px;
--space-sm:8px;
--space-md:16px;
--space-lg:28px;
--space-xl:44px;
--radius-sm:6px;
--radius-md:14px;
--radius-lg:24px;
--radius-full:999px;
--font-hero:2.4rem;
--font-title:1.4rem;
--font-body:1rem;
--font-sm:0.82rem;
--font-xs:0.72rem;
--shadow-sm:0 2px 12px rgba(0,0,0,0.4);
--shadow-md:0 12px 32px rgba(0,0,0,0.55);
--shadow-lg:0 24px 64px rgba(0,0,0,0.7);
--shadow-glow:0 0 24px rgba(199,125,107,0.25);
--transition-fast:150ms ease;
--transition-base:280ms cubic-bezier(0.16,1,0.3,1);
--transition-slow:600ms cubic-bezier(0.16,1,0.3,1);
--ease-out:cubic-bezier(0.16,1,0.3,1);
}
html{font-size:16px;-webkit-text-size-adjust:100%;}
body{
background:var(--color-bg);
color:var(--color-text);
font-family:"PingFang SC","Hiragino Sans GB","Microsoft YaHei",system-ui,-apple-system,sans-serif;
line-height:1.65;
min-height:100vh;
display:flex;
flex-direction:column;
overflow-x:hidden;
-webkit-font-smoothing:antialiased;
}
.atmo-bg{
position:fixed;
inset:0;
z-index:0;
pointer-events:none;
background:
radial-gradient(ellipse 80% 60% at 20% 10%,rgba(199,125,107,0.08),transparent 60%),
radial-gradient(ellipse 70% 50% at 85% 90%,rgba(120,80,100,0.12),transparent 60%),
radial-gradient(ellipse 50% 40% at 50% 50%,rgba(207,170,122,0.04),transparent 70%);
}
.atmo-grain{
position:fixed;
inset:0;
z-index:1;
pointer-events:none;
opacity:0.035;
background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
background-size:180px;
mix-blend-mode:overlay;
}
.mote{
position:fixed;
width:3px;
height:3px;
border-radius:50%;
background:var(--color-gold);
opacity:0;
pointer-events:none;
z-index:2;
filter:blur(0.5px);
}
@keyframes moteFloat{
0%{opacity:0;transform:translateY(0) scale(0.5);}
15%{opacity:0.6;}
50%{opacity:0.3;}
85%{opacity:0.5;}
100%{opacity:0;transform:translateY(-90vh) scale(1.2);}
}
.mote:nth-child(1){left:8%;animation:moteFloat 14s ease-in infinite;animation-delay:0s;}
.mote:nth-child(2){left:22%;animation:moteFloat 18s ease-in infinite;animation-delay:3s;width:2px;height:2px;}
.mote:nth-child(3){left:41%;animation:moteFloat 16s ease-in infinite;animation-delay:7s;}
.mote:nth-child(4){left:63%;animation:moteFloat 20s ease-in infinite;animation-delay:1s;width:4px;height:4px;opacity:0.15;}
.mote:nth-child(5){left:78%;animation:moteFloat 15s ease-in infinite;animation-delay:5s;}
.mote:nth-child(6){left:92%;animation:moteFloat 17s ease-in infinite;animation-delay:9s;width:2px;height:2px;}
#intro-overlay{
position:fixed;
inset:0;
z-index:999;
background:radial-gradient(circle at 50% 45%,#1c1418 0%,#0a0709 100%);
display:flex;
align-items:center;
justify-content:center;
flex-direction:column;
transition:opacity 1s var(--ease-out),visibility 1s;
}
#intro-overlay.hidden{
opacity:0;
visibility:hidden;
pointer-events:none;
}
.intro-ring{
width:120px;
height:120px;
border-radius:50%;
border:1px solid rgba(199,125,107,0.3);
position:relative;
animation:introSpin 4s linear infinite;
}
.intro-ring::before,.intro-ring::after{
content:"";
position:absolute;
border-radius:50%;
border:1px solid transparent;
}
.intro-ring::before{
inset:14px;
border-top-color:var(--color-accent);
border-right-color:rgba(207,170,122,0.4);
animation:introSpin 2.2s linear infinite reverse;
}
.intro-ring::after{
inset:34px;
border-bottom-color:var(--color-primary);
border-left-color:rgba(199,125,107,0.3);
animation:introSpin 1.6s linear infinite;
}
@keyframes introSpin{to{transform:rotate(360deg);}}
.intro-text{
margin-top:var(--space-lg);
font-size:var(--font-xs);
letter-spacing:0.5em;
text-indent:0.5em;
color:var(--color-text-muted);
animation:introPulse 2.4s ease-in-out infinite;
}
@keyframes introPulse{0%,100%{opacity:0.4;}50%{opacity:1;}}
.intro-skip{
position:absolute;
top:var(--space-lg);
right:var(--space-lg);
background:transparent;
border:1px solid var(--color-border);
color:var(--color-text-muted);
padding:var(--space-sm) var(--space-md);
border-radius:var(--radius-full);
font-size:var(--font-xs);
cursor:pointer;
letter-spacing:0.1em;
transition:all var(--transition-base);
min-height:44px;
min-width:44px;
}
.intro-skip:hover{
border-color:var(--color-primary);
color:var(--color-accent);
}
main{
position:relative;
z-index:3;
flex:1;
width:100%;
max-width:880px;
margin:0 auto;
padding:var(--space-xl) var(--space-md) 120px;
}
.reveal{
opacity:0;
transform:translateY(24px);
animation:revealUp 1s var(--ease-out) forwards;
}
@keyframes revealUp{
to{opacity:1;transform:translateY(0);}
}
.reveal-d1{animation-delay:0.15s;}
.reveal-d2{animation-delay:0.3s;}
.reveal-d3{animation-delay:0.45s;}
.reveal-d4{animation-delay:0.6s;}
.reveal-d5{animation-delay:0.75s;}
.reveal-d6{animation-delay:0.9s;}
.hero{
text-align:center;
padding:var(--space-lg) 0 var(--space-xl);
position:relative;
}
.hero-kicker{
font-size:var(--font-xs);
letter-spacing:0.6em;
text-indent:0.6em;
color:var(--color-gold);
text-transform:uppercase;
margin-bottom:var(--space-md);
opacity:0.85;
}
.hero-title{
font-size:var(--font-hero);
font-weight:800;
letter-spacing:0.08em;
line-height:1.15;
background:linear-gradient(135deg,#f5e6dc 0%,#e7b49b 40%,#c77d6b 70%,#a05f52 100%);
-webkit-background-clip:text;
background-clip:text;
-webkit-text-fill-color:transparent;
color:transparent;
margin-bottom:var(--space-sm);
position:relative;
}
.hero-title::after{
content:"";
display:block;
width:56px;
height:2px;
margin:var(--space-md) auto 0;
background:linear-gradient(90deg,transparent,var(--color-gold),transparent);
animation:lineBreath 3s ease-in-out infinite;
}
@keyframes lineBreath{0%,100%{opacity:0.4;width:40px;}50%{opacity:1;width:90px;}}
.hero-sub{
font-size:var(--font-sm);
color:var(--color-text-muted);
letter-spacing:0.2em;
margin-top:var(--space-sm);
}
.section{
margin-bottom:var(--space-xl);
position:relative;
}
.section-head{
display:flex;
align-items:baseline;
gap:var(--space-sm);
margin-bottom:var(--space-lg);
position:relative;
}
.section-num{
font-size:var(--font-xs);
color:var(--color-gold);
letter-spacing:0.3em;
font-weight:700;
opacity:0.7;
}
.section-title{
font-size:var(--font-title);
font-weight:700;
letter-spacing:0.12em;
color:var(--color-accent);
position:relative;
padding-bottom:var(--space-sm);
}
.section-title::after{
content:"";
position:absolute;
left:0;
bottom:0;
width:100%;
height:1px;
background:linear-gradient(90deg,var(--color-primary),transparent);
transform-origin:left;
animation:underlineGrow 1.2s var(--ease-out) forwards;
}
@keyframes underlineGrow{from{transform:scaleX(0);}to{transform:scaleX(1);}}
.card{
background:var(--color-surface);
backdrop-filter:blur(14px);
-webkit-backdrop-filter:blur(14px);
border:1px solid var(--color-border);
border-radius:var(--radius-lg);
padding:var(--space-lg);
box-shadow:var(--shadow-md);
position:relative;
overflow:hidden;
transition:transform var(--transition-base),box-shadow var(--transition-base),border-color var(--transition-base);
}
.card::before{
content:"";
position:absolute;
top:0;
left:0;
right:0;
height:1px;
background:linear-gradient(90deg,transparent,rgba(231,180,155,0.5),transparent);
opacity:0.6;
}
.card:hover{
transform:translateY(-4px);
box-shadow:var(--shadow-lg),var(--shadow-glow);
border-color:rgba(199,125,107,0.35);
}
.story-text{
font-size:var(--font-body);
line-height:2;
color:var(--color-text);
letter-spacing:0.02em;
}
.story-text em{
font-style:normal;
color:var(--color-accent);
font-weight:600;
}
.story-text .highlight{
color:var(--color-gold);
font-weight:600;
border-bottom:1px dashed rgba(207,170,122,0.4);
}
.story-divider{
display:flex;
align-items:center;
gap:var(--space-md);
margin:var(--space-md) 0;
color:var(--color-gold);
font-size:var(--font-xs);
letter-spacing:0.3em;
opacity:0.5;
}
.story-divider::before,.story-divider::after{
content:"";
flex:1;
height:1px;
background:linear-gradient(90deg,transparent,var(--color-border),transparent);
}
.char-grid{
display:grid;
grid-template-columns:1fr 1fr;
gap:var(--space-md);
}
.char-card{
background:var(--color-surface);
backdrop-filter:blur(14px);
-webkit-backdrop-filter:blur(14px);
border:1px solid var(--color-border);
border-radius:var(--radius-lg);
padding:var(--space-md);
box-shadow:var(--shadow-sm);
position:relative;
overflow:hidden;
transition:all var(--transition-base);
cursor:pointer;
min-height:44px;
}
.char-card:hover{
transform:translateY(-6px) scale(1.012);
box-shadow:var(--shadow-md),0 0 30px rgba(199,125,107,0.18);
border-color:rgba(199,125,107,0.4);
}
.char-card::after{
content:"";
position:absolute;
top:-50%;
left:-50%;
width:200%;
height:200%;
background:conic-gradient(from 0deg,transparent,rgba(199,125,107,0.06),transparent 30%);
animation:charShine 6s linear infinite;
pointer-events:none;
}
@keyframes charShine{to{transform:rotate(360deg);}}
.char-portrait{
display:block;
width:256px;
height:341px;
max-width:100%;
margin:0 auto var(--space-md);
border-radius:var(--radius-md);
background-size:cover;
background-position:center;
background-repeat:no-repeat;
box-shadow:var(--shadow-md);
position:relative;
z-index:1;
}
.portrait-sunian{
background-image:url('https://catai.wiki/9cbb9ada-4afd-4a6b-d72c-b9db9b424900/w=3000');
}
.portrait-suhui{
background-image:url('https://catai.wiki/8895f373-4471-4f47-566a-b9b35c9ecc00/w=3000');
}
.char-name{
font-size:1.15rem;
font-weight:700;
letter-spacing:0.08em;
margin-bottom:var(--space-xs);
color:var(--color-text);
position:relative;
z-index:1;
}
.char-tag{
font-size:var(--font-xs);
color:var(--color-gold);
letter-spacing:0.15em;
margin-bottom:var(--space-sm);
opacity:0.8;
position:relative;
z-index:1;
}
.char-desc{
font-size:var(--font-sm);
color:var(--color-text-muted);
line-height:1.75;
max-height:0;
overflow:hidden;
transition:max-height 0.5s var(--ease-out),margin 0.4s var(--ease-out);
position:relative;
z-index:1;
}
.char-card.expanded .char-desc{
max-height:600px;
margin-top:var(--space-sm);
}
.char-meta{
display:flex;
flex-wrap:wrap;
gap:var(--space-xs);
margin-top:var(--space-sm);
position:relative;
z-index:1;
}
.char-meta span{
font-size:var(--font-xs);
padding:2px 10px;
border-radius:var(--radius-full);
border:1px solid var(--color-border);
color:var(--color-text-muted);
letter-spacing:0.05em;
transition:all var(--transition-fast);
}
.char-card:hover .char-meta span{
border-color:rgba(199,125,107,0.4);
color:var(--color-accent);
}
.male-card{
background:var(--color-surface);
backdrop-filter:blur(14px);
-webkit-backdrop-filter:blur(14px);
border:1px solid var(--color-border);
border-radius:var(--radius-lg);
padding:var(--space-lg);
box-shadow:var(--shadow-sm);
display:flex;
gap:var(--space-lg);
align-items:flex-start;
transition:all var(--transition-base);
}
.male-card:hover{
border-color:rgba(199,125,107,0.35);
box-shadow:var(--shadow-md),0 0 30px rgba(207,170,122,0.12);
}
.male-card .char-avatar{
flex-shrink:0;
width:64px;
height:64px;
font-size:1.7rem;
}
.male-info h3{
font-size:1.15rem;
font-weight:700;
letter-spacing:0.08em;
margin-bottom:var(--space-xs);
}
.male-info .char-tag{margin-bottom:var(--space-sm);}
.male-info p{
font-size:var(--font-sm);
color:var(--color-text-muted);
line-height:1.8;
}
.char-avatar{
width:56px;
height:56px;
border-radius:50%;
display:flex;
align-items:center;
justify-content:center;
font-size:1.5rem;
font-weight:700;
margin-bottom:var(--space-md);
position:relative;
border:1px solid var(--color-border);
}
.avatar-male{
background:linear-gradient(135deg,#2e2a1a,#1e1a12);
color:#cfaa7a;
}
.scene-card{
background:linear-gradient(135deg,rgba(40,28,32,0.9),rgba(24,18,22,0.9));
border:1px solid rgba(199,125,107,0.25);
border-radius:var(--radius-lg);
padding:var(--space-lg);
box-shadow:var(--shadow-md),inset 0 0 60px rgba(199,125,107,0.04);
position:relative;
overflow:hidden;
}
.scene-card::before{
content:"";
position:absolute;
top:0;
left:0;
width:100%;
height:3px;
background:linear-gradient(90deg,var(--color-primary),var(--color-gold),var(--color-primary));
background-size:200% 100%;
animation:sceneBar 3s linear infinite;
}
@keyframes sceneBar{to{background-position:200% 0;}}
.scene-card .story-text{
font-size:var(--font-body);
line-height:2.1;
}
.scene-card .story-text strong{
color:var(--color-accent);
font-weight:700;
}
.scene-card .story-text .whisper{
color:var(--color-gold);
font-style:italic;
opacity:0.9;
}
.form-card{
background:var(--color-surface);
backdrop-filter:blur(14px);
-webkit-backdrop-filter:blur(14px);
border:1px solid var(--color-border);
border-radius:var(--radius-lg);
padding:var(--space-lg);
box-shadow:var(--shadow-sm);
}
.form-group{margin-bottom:var(--space-md);}
.form-group label{
display:block;
font-size:var(--font-xs);
color:var(--color-gold);
letter-spacing:0.15em;
margin-bottom:var(--space-xs);
text-transform:uppercase;
}
.form-group input[type="text"],
.form-group textarea{
width:100%;
padding:12px 14px;
border-radius:var(--radius-md);
border:1px solid var(--color-border);
background:rgba(0,0,0,0.35);
color:var(--color-text);
font-size:var(--font-body);
font-family:inherit;
outline:none;
transition:border-color var(--transition-base),box-shadow var(--transition-base);
min-height:44px;
}
.form-group input[type="text"]:focus,
.form-group textarea:focus{
border-color:var(--color-primary);
box-shadow:0 0 0 3px rgba(199,125,107,0.12);
}
.form-group input::placeholder,
.form-group textarea::placeholder{color:#6b5a5e;}
.form-group textarea{resize:vertical;min-height:64px;line-height:1.6;}
.form-row{
display:grid;
grid-template-columns:repeat(3,1fr);
gap:var(--space-md);
}
.form-row .form-group{margin-bottom:0;}
.form-row input[type="range"]{
width:100%;
height:44px;
background:transparent;
-webkit-appearance:none;
appearance:none;
cursor:pointer;
}
.form-row input[type="range"]::-webkit-slider-runnable-track{
height:3px;
background:linear-gradient(90deg,var(--color-primary),var(--color-gold));
border-radius:2px;
}
.form-row input[type="range"]::-webkit-slider-thumb{
-webkit-appearance:none;
appearance:none;
width:20px;
height:20px;
margin-top:-8.5px;
border-radius:50%;
background:var(--color-accent);
border:2px solid rgba(255,255,255,0.2);
box-shadow:0 0 10px rgba(231,180,155,0.6);
}
.form-row input[type="range"]::-moz-range-track{
height:3px;
background:linear-gradient(90deg,var(--color-primary),var(--color-gold));
border-radius:2px;
}
.form-row input[type="range"]::-moz-range-thumb{
width:20px;
height:20px;
border-radius:50%;
background:var(--color-accent);
border:2px solid rgba(255,255,255,0.2);
box-shadow:0 0 10px rgba(231,180,155,0.6);
}
.range-val{
font-size:var(--font-sm);
color:var(--color-accent);
font-weight:600;
text-align:center;
margin-top:var(--space-xs);
display:block;
}
.choice-grid{
display:flex;
flex-direction:column;
gap:var(--space-md);
margin-top:var(--space-lg);
}
.choice-btn{
display:flex;
align-items:flex-start;
gap:var(--space-md);
padding:var(--space-lg) var(--space-md);
background:var(--color-surface);
border:1px solid var(--color-border);
border-radius:var(--radius-lg);
cursor:pointer;
transition:all var(--transition-base);
position:relative;
overflow:hidden;
text-align:left;
color:var(--color-text);
font-size:var(--font-body);
font-family:inherit;
line-height:1.6;
min-height:44px;
}
.choice-btn::before{
content:"";
position:absolute;
inset:0;
background:radial-gradient(circle at var(--mx,50%) var(--my,50%),rgba(199,125,107,0.15),transparent 60%);
opacity:0;
transition:opacity 0.4s;
}
.choice-btn:hover::before{opacity:1;}
.choice-btn:hover{
border-color:var(--color-primary);
transform:translateX(6px);
box-shadow:var(--shadow-md),0 0 30px rgba(199,125,107,0.15);
background:rgba(40,28,32,0.85);
}
.choice-btn:active{transform:translateX(6px) scale(0.985);}
.choice-btn .choice-icon{
flex-shrink:0;
width:42px;
height:42px;
border-radius:var(--radius-md);
display:flex;
align-items:center;
justify-content:center;
font-size:1.2rem;
background:rgba(199,125,107,0.12);
border:1px solid rgba(199,125,107,0.2);
transition:all var(--transition-base);
}
.choice-btn:hover .choice-icon{
background:rgba(199,125,107,0.25);
transform:scale(1.08) rotate(-4deg);
border-color:var(--color-primary);
}
.choice-content{flex:1;}
.choice-content .choice-title{
font-weight:700;
color:var(--color-accent);
font-size:1.05rem;
letter-spacing:0.06em;
margin-bottom:var(--space-xs);
display:block;
}
.choice-content .choice-desc{
font-size:var(--font-sm);
color:var(--color-text-muted);
line-height:1.7;
}
.choice-btn::after{
content:"";
position:absolute;
right:var(--space-md);
top:50%;
transform:translateY(-50%);
width:8px;
height:8px;
border-radius:50%;
background:var(--color-primary);
opacity:0;
transition:all var(--transition-base);
}
.choice-btn:hover::after{
opacity:1;
animation:pulseDot 1.2s ease-in-out infinite;
}
@keyframes pulseDot{
0%,100%{box-shadow:0 0 0 0 rgba(199,125,107,0.5);}
50%{box-shadow:0 0 0 8px rgba(199,125,107,0);}
}
.hint-bubble{
margin-top:var(--space-lg);
padding:var(--space-md) var(--space-lg);
background:rgba(199,125,107,0.06);
border:1px solid rgba(199,125,107,0.15);
border-radius:var(--radius-md);
font-size:var(--font-sm);
color:var(--color-text-muted);
display:flex;
align-items:center;
gap:var(--space-sm);
animation:hintFloat 4s ease-in-out infinite;
}
@keyframes hintFloat{0%,100%{transform:translateY(0);}50%{transform:translateY(-4px);}}
.hint-bubble::before{
content:"✦";
color:var(--color-gold);
font-size:0.9rem;
}
.copy-bar{
position:fixed;
left:0;
right:0;
bottom:0;
