<div class="copy-bar">
<button class="copy-btn" id="copyPreset">复制主角设定 · 开始</button>
</div>
<div class="toast" id="toast">已复制，粘贴到 AI 即可开局</div>
<script>
(function(){
"use strict";
var overlay=document.getElementById('intro-overlay');
var skipBtn=document.getElementById('skipIntro');
var introDone=false;
function closeIntro(){
if(introDone)return;
introDone=true;
overlay.classList.add('hidden');
setTimeout(function(){
if(overlay.parentNode)overlay.parentNode.removeChild(overlay);
},1100);
}
var prefersReduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(prefersReduced){
closeIntro();
}else{
var introTimer=setTimeout(closeIntro,3200);
skipBtn.addEventListener('click',function(){
clearTimeout(introTimer);
closeIntro();
});
}
var charCards=document.querySelectorAll('.char-card');
charCards.forEach(function(card){
function toggle(){
card.classList.toggle('expanded');
}
card.addEventListener('click',toggle);
card.addEventListener('keydown',function(e){
if(e.key==='Enter'||e.key===' '){
e.preventDefault();
toggle();
}
});
});
var choiceBtns=document.querySelectorAll('.choice-btn');
choiceBtns.forEach(function(btn){
btn.addEventListener('click',function(){
var choice=btn.getAttribute('data-choice');
var title=btn.querySelector('.choice-title').textContent;
var rect=btn.getBoundingClientRect();
var ripple=document.createElement('span');
ripple.style.cssText='position:absolute;border-radius:50%;background:rgba(231,180,155,0.25);transform:scale(0);animation:rippleAnim 0.6s ease-out forwards;pointer-events:none;';
var size=Math.max(rect.width,rect.height);
ripple.style.width=size+'px';
ripple.style.height=size+'px';
ripple.style.left=(rect.width/2-size/2)+'px';
ripple.style.top=(rect.height/2-size/2)+'px';
btn.appendChild(ripple);
setTimeout(function(){ripple.remove();},650);
btn.style.borderColor='rgba(207,170,122,0.6)';
setTimeout(function(){
btn.style.borderColor='';
},800);
console.log('[开局选择] '+choice+' — '+title);
});
btn.addEventListener('mousemove',function(e){
var rect=btn.getBoundingClientRect();
btn.style.setProperty('--mx',((e.clientX-rect.left)/rect.width*100)+'%');
btn.style.setProperty('--my',((e.clientY-rect.top)/rect.height*100)+'%');
});
});
var styleSheet=document.createElement('style');
styleSheet.textContent='@keyframes rippleAnim{to{transform:scale(2.5);opacity:0;}}';
document.head.appendChild(styleSheet);
var lengthSlider=document.getElementById('p-length');
var girthSlider=document.getElementById('p-girth');
var staminaSlider=document.getElementById('p-stamina');
var vLength=document.getElementById('v-length');
var vGirth=document.getElementById('v-girth');
var vStamina=document.getElementById('v-stamina');
function updateRange(){
vLength.textContent=lengthSlider.value+' cm';
vGirth.textContent=girthSlider.value+' cm';
vStamina.textContent=staminaSlider.value+' min';
}
lengthSlider.addEventListener('input',updateRange);
girthSlider.addEventListener('input',updateRange);
staminaSlider.addEventListener('input',updateRange);
var toast=document.getElementById('toast');
function showToast(){
toast.classList.add('show');
setTimeout(function(){toast.classList.remove('show');},2200);
}
function fallbackCopy(text){
var ta=document.createElement('textarea');
ta.value=text;
ta.style.cssText='position:fixed;left:-9999px;top:0';
document.body.appendChild(ta);
ta.focus();
ta.select();
try{
if(document.execCommand('copy'))showToast();
else alert('复制失败，请手动长按选择复制');
}catch(e){
alert('复制失败，请手动长按选择复制');
}
document.body.removeChild(ta);
}
var copyBtn=document.getElementById('copyPreset');
copyBtn.addEventListener('click',function(){
var name=document.getElementById('p-name').value.trim()||'未命名';
var identity=document.getElementById('p-identity').value.trim()||'姐夫 / 都市上班族';
var personality=document.getElementById('p-personality').value.trim()||'精虫上脑，占有欲强，喜欢掌控';
var length=lengthSlider.value;
var girth=girthSlider.value;
var stamina=staminaSlider.value;
var text='【主角设定】\n· 姓名：'+name+'\n· 身份：'+identity+'\n· 性格：'+personality+'\n· 身体数据：长度 '+length+'cm · 周径 '+girth+'cm · 持久力约 '+stamina+' 分钟\n—— 以第一人称「我」进入游戏 ——\n开局前情：老婆一早去医院产检。小姨子苏念带着胎教CD上门，我下楼买咖啡，忘了收影碟机旁的A片，赶回家时她已经打开在看。挂掉老婆说晚归的电话，整个下午家里只剩我们俩。我悄悄往她那边挪了半寸。';
if(navigator.clipboard&&window.isSecureContext){
navigator.clipboard.writeText(text).then(showToast).catch(function(){fallbackCopy(text);});
}else{
fallbackCopy(text);
}
});
})();
</script>
</body>
</html>

