/* ===== 状态栏折叠 ===== */
details {
  display: block;
  margin: 0;
  padding: 0;
  background: linear-gradient(180deg, rgba(38,18,30,.98), rgba(22,11,18,.96));
  border-top: 1px solid rgba(255,111,163,.2);
  border-bottom: 1px solid rgba(255,111,163,.28);
}

details[open] {
  background: linear-gradient(180deg, rgba(44,20,34,.99), rgba(24,12,20,.97));
}

summary {
  display: block;
  padding: 14px 22px;
  font-weight: 700;
  color: #ff6fa3;
  font-size: 13.2px;
  cursor: pointer;
  list-style: none;
  text-shadow: 0 0 8px rgba(255,111,163,.45);
  letter-spacing: 2px;
  user-select: none;
}

summary::-webkit-details-marker { display: none; }
summary::after { content: " ▸"; font-size: 10px; opacity: .8; margin-left: 5px; }
details[open] summary::after { content: " ▾"; }

field {
  display: block;
  margin: 0;
  padding: 6px 22px;
  font-size: 12.7px;
  line-height: 1.78;
  color: #c8b0bc;
  border-bottom: 1px solid rgba(255,255,255,.03);
}

field-os {
  display: block;
  margin: 0;
  padding: 6px 22px;
  font-size: 12.7px;
  line-height: 1.78;
  color: #e8c8a8;
  font-style: italic;
  border-bottom: 1px solid rgba(255,255,255,.03);
}

/* ===== 选择栏 ===== */
choice-panel {
  display: block;
  padding: 18px 18px 24px;
  background: linear-gradient(0deg, rgba(16,8,14,.98) 55%, rgba(26,12,20,.35));
}

opt {
  display: block;
  width: 100%;
  margin: 0 0 10px;
  padding: 14px 18px;
  border: 1px solid rgba(255,111,163,.38);
  border-radius: 13px;
  background: linear-gradient(150deg, #2a121e, #12080e 48%, #24121c);
  color: #efe0e8;
  font-size: 13.8px;
  line-height: 1.6;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 3px 14px rgba(0,0,0,.48);
  transition: transform .2s, border-color .22s, box-shadow .22s;
}

opt:last-child { margin-bottom: 0; }

opt:hover {
  transform: translateX(4px) translateY(-1.5px);
  border-color: rgba(255,111,163,.85);
  box-shadow: 0 8px 24px rgba(255,111,163,.4);
  color: #fff;
}

/* ===== 移动端适配 ===== */
@media (max-width: 480px) {
  ai { border-radius: 0; max-width: 100%; }
  user-card { padding: 15px 16px 13px; }
  text { padding: 22px 16px 18px; font-size: 15px; }
  para, line { text-indent: 1.6em; }
  sense { margin-left: 0; }
  field, field-os { padding-left: 16px; padding-right: 16px; font-size: 12.3px; }
  summary { padding-left: 16px; padding-right: 16px; }
  choice-panel { padding: 15px 14px 20px; }
  opt { padding: 13px 15px; font-size: 13.4px; }
  ex-01,ex-02,ex-03,ex-04,ex-05,ex-06,ex-07,ex-08,ex-09,ex-10,ex-11,ex-12,
